      const hi = this.parseConstIndex(`the selection on '${hierToStr({ path, sel: null })}'`);
      sel = this.at(':') ? (this.next(), { hi, lo: this.parseConstIndex(`the selection on '${hierToStr({ path, sel: null })}'`) }) : { hi, lo: hi };
